import { Hono } from 'hono';
import { type Config, loadConfig } from './config';
import { AuditLog } from './lib/audit';
import { EventStore } from './lib/store';
import { TenantRegistry } from './lib/tenants';
import { adminRoutes } from './routes/admin';
import { auditRoutes } from './routes/audit';
import { eventRoutes } from './routes/events';
import { webhookRoutes } from './routes/webhooks';

export interface Deps {
  config: Config;
  store: EventStore;
  tenants: TenantRegistry;
  audit: AuditLog;
}

export function createDeps(config: Config = loadConfig()): Deps {
  return {
    config,
    store: new EventStore(),
    tenants: new TenantRegistry([
      { id: 'tenant-a', name: 'Tenant A' },
      { id: 'tenant-b', name: 'Tenant B' },
    ]),
    audit: new AuditLog(),
  };
}

export function createApp(deps: Deps = createDeps()): Hono {
  const app = new Hono();
  app.get('/health', (c) => c.json({ ok: true }));
  app.route('/webhooks', webhookRoutes(deps));
  app.route('/events', eventRoutes(deps));
  app.route('/admin', adminRoutes(deps));
  app.route('/audit', auditRoutes(deps));
  return app;
}
