import { setup } from './helpers';

describe('POST /webhooks', () => {
  it('accepts an event for a known tenant', async () => {
    const { postWebhook } = setup();
    const res = await postWebhook('tenant-a', { type: 'invoice.paid', data: { amount: 10 } });
    expect(res.status).toBe(202);
    const body = await res.json();
    expect(body).toMatchObject({ id: 'evt_000001', tenant: 'tenant-a', type: 'invoice.paid', attempts: 0 });
  });

  it('rejects a request without the X-Tenant header', async () => {
    const { send } = setup();
    const res = await send('/webhooks', { method: 'POST', body: JSON.stringify({ type: 'x' }) });
    expect(res.status).toBe(400);
  });

  it('rejects an unknown tenant', async () => {
    const { postWebhook } = setup();
    expect((await postWebhook('nobody', { type: 'x' })).status).toBe(404);
  });

  it('rejects a body that is not JSON', async () => {
    const { send } = setup();
    const res = await send('/webhooks', { method: 'POST', tenant: 'tenant-a', body: 'not json' });
    expect(res.status).toBe(400);
  });

  it('rejects an event without a type', async () => {
    const { postWebhook } = setup();
    expect((await postWebhook('tenant-a', { data: 1 })).status).toBe(400);
  });

  it('rejects a payload over the configured size', async () => {
    const { postWebhook } = setup({ maxBodyBytes: 32 });
    const res = await postWebhook('tenant-a', { type: 'big', data: 'x'.repeat(64) });
    expect(res.status).toBe(413);
  });

  it('writes an audit entry for each accepted event', async () => {
    const { postWebhook, deps } = setup();
    await postWebhook('tenant-a', { type: 'invoice.paid' });
    expect(deps.audit.list()).toMatchObject([{ tenant: 'tenant-a', action: 'webhook.received', target: 'evt_000001' }]);
